 public static Integer[] BubbleSort(Integer[] DataArray){
        Boolean Swap = true;
        Integer Temp;
       while(Swap){
              Swap = false;
              for(Integer X = 0; X < DataArray.length - 1; X++){
                     if(DataArray[X] > DataArray[X+1]){
                           Temp = DataArray[X];
                           DataArray[X] = DataArray[X + 1];
                           DataArray[X + 1] = Temp;
                           Swap = true;
                     }
              }
        }
        return DataArray;
 }
