 def BubbleSort(DataArray):
      Swap = True
      while Swap  == True:
           Swap = False
           for y in range(0, len(DataArray)-1):
               if DataArray[y] > DataArray[y+1]:
                    DataArray[y], DataArray[y+1] = DataArray[y+1], DataArray[y]
                    Swap = True
      return DataArray

